const c=document.querySelector('#game'),ctx=c.getContext('2d');
const mode='dodge';
let x=172,items=[],score=0,lives=3,running=false,last=0,spawn=0,id=0,elapsed=0;
const keys=new Set();
function ui(){document.querySelector('#score').textContent='Score: '+score;document.querySelector('#lives').textContent=mode==='catch'?'Time: '+Math.max(0,Math.ceil(30-elapsed)):'Lives: '+lives;}
function paint(){ctx.clearRect(0,0,380,410);ctx.fillStyle='#344368';for(let i=0;i<35;i++)ctx.fillRect(i*137%380,(i*89+elapsed*25)%410,2,2);ctx.font='30px system-ui';ctx.textBaseline='top';ctx.fillStyle='#b6a4ff';if(mode==='catch'){ctx.beginPath();ctx.moveTo(x,368);ctx.lineTo(x+34,368);ctx.lineTo(x+28,394);ctx.lineTo(x+6,394);ctx.closePath();ctx.fill();ctx.strokeStyle='#d6cbff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x+17,368,12,Math.PI,0);ctx.stroke();}else{ctx.beginPath();ctx.moveTo(x+16,361);ctx.lineTo(x+32,395);ctx.lineTo(x+16,387);ctx.lineTo(x,395);ctx.closePath();ctx.fill();ctx.fillStyle='#5eead4';ctx.fillRect(x+13,374,6,8);}for(const o of items){if(mode==='catch'){ctx.fillStyle='#ffd76f';ctx.beginPath();ctx.arc(o.x+13,o.y+13,13,0,Math.PI*2);ctx.fill();ctx.fillStyle='#8b5f12';ctx.font='16px system-ui';ctx.fillText('T',o.x+8,o.y+3);}else{ctx.fillStyle='#b6a4ff';ctx.fillRect(o.x,o.y,26,26);}}}
function start(){cancelAnimationFrame(id);x=172;items=[];score=0;lives=3;elapsed=0;spawn=0;last=0;running=true;keys.clear();document.querySelector('#status').textContent=mode==='catch'?'Catch as many coins as you can!':'Dodge the blocks!';document.querySelector('#start').textContent='Restart';c.focus();id=requestAnimationFrame(frame);}
function frame(time){if(!running)return;const dt=last?Math.min((time-last)/1000,.05):0;last=time;elapsed+=dt;if(keys.has('ArrowLeft'))x-=300*dt;if(keys.has('ArrowRight'))x+=300*dt;x=Math.max(0,Math.min(346,x));spawn+=dt;if(spawn>.55){spawn=0;items.push({x:Math.random()*354,y:-26});}for(const o of items){o.y+=(mode==='catch'?195:165+elapsed*2)*dt;if(x<o.x+26&&x+32>o.x&&365<o.y+26&&397>o.y){o.hit=true;if(mode==='catch')score+=10;else lives--;}}items=items.filter(o=>{if(o.hit)return false;if(o.y>410){if(mode==='dodge')score++;return false;}return true;});ui();paint();if(lives<=0||mode==='catch'&&elapsed>=30){running=false;document.querySelector('#status').textContent='Game over! Score: '+score+'. Try again!';return;}id=requestAnimationFrame(frame);}
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();keys.add(e.key);}});window.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>keys.clear());
function move(e){const r=c.getBoundingClientRect();x=Math.max(0,Math.min(346,(e.clientX-r.left)*380/r.width-16));if(!running)paint();}c.addEventListener('pointermove',move);c.addEventListener('pointerdown',e=>{c.setPointerCapture(e.pointerId);move(e);});
for(const [name,key] of [['left','ArrowLeft'],['right','ArrowRight']]){const b=document.querySelector('#'+name);b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(key)};b.onpointerup=b.onpointercancel=()=>keys.delete(key);}
document.querySelector('#start').onclick=start;paint();ui();

