const board=document.querySelector('#board');let first=null,locked=false,moves=0,pairs=0,round=0;
function reset(){round++;first=null;locked=false;moves=0;pairs=0;document.querySelector('#stats').textContent='Moves: 0';document.querySelector('#status').textContent='Find 8 pairs!';board.replaceChildren();const cards=[...'★◆●▲♥■✚☾'];const deck=cards.flatMap(x=>[x,x]);for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}for(const [index,symbol] of deck.entries()){const b=document.createElement('button');b.textContent='?';b.setAttribute('aria-label','Hidden card '+(index+1));b.onclick=()=>{if(locked||b.classList.contains('matched')||b===first)return;b.textContent=symbol;b.setAttribute('aria-label',symbol);if(!first){first=b;return;}moves++;document.querySelector('#stats').textContent='Moves: '+moves;const a=first;first=null;if(a.textContent===symbol){a.classList.add('matched');b.classList.add('matched');pairs++;if(pairs===8)document.querySelector('#status').textContent='You won in '+moves+' moves!';}else{locked=true;const r=round;setTimeout(()=>{if(r!==round)return;a.textContent=b.textContent='?';a.setAttribute('aria-label','Hidden card');b.setAttribute('aria-label','Hidden card');locked=false;},750);}};board.appendChild(b);}}
document.querySelector('#reset').onclick=reset;reset();
